 "content": "def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    blocks = []
    for r in range(h - 1):
        for c in range(w - 1):
            if all(grid[rr][cc] == 2 for rr in (r, r + 1) for cc in (c, c + 1)):
                if r > 0 and r + 2 < h and c > 0 and c + 2 < w:
                    # The four diagonal cells surrounding a 2x2 block.
                    coords = {
                        'tl': (r - 1, c - 1), 'tr': (r - 1, c + 2),
                        'bl': (r + 2, c - 1), 'br': (r + 2, c + 2),
                    }
                    if all(grid[rr][cc] not in (0, 2) for rr, cc in coords.values()):
                        blocks.append(coords)
    # Rotate the four corner colors clockwise, then extend each outward
    # along the corresponding diagonal until the grid edge.
    for q in blocks:
        old = {k: grid[r][c] for k, (r, c) in q.items()}
        assigned = {'tl': old['bl'], 'tr': old['tl'], 'br': old['tr'], 'bl': old['br']}
        directions = {'tl': (-1, -1), 'tr': (-1, 1), 'bl': (1, -1), 'br': (1, 1)}
        for k, (r, c) in q.items():
            color = assigned[k]
            dr, dc = directions[k]
            rr, cc = r, c
            while 0 <= rr < h and 0 <= cc < w:
                out[rr][cc] = color
                rr += dr
                cc += dc
    return out


